import {createSlice, createAsyncThunk} from '@reduxjs/toolkit'
import axios from 'axios';
import {SERVER}  from '../../utils/utils'
import * as FileSystem from 'expo-file-system'


/**
 * Thunks
 */

 // Constants
//  const LOCAL_SERVER='localhost'
//  const SERVER = LOCAL_SERVER;
 const SECTION_QUESTION = 'http://'+SERVER+':8080/api/v1/yuva/hra/questions/9'
 const SUBMISSION_QUESTION = 'http://'+SERVER+':8080/api/v1/yuva/hra/answers2'
 const DOWNLOAD_REPORT = 'http://'+SERVER+':8080/api/v1/yuva/hraPdfReport'
 const CHECK_REPORT = 'http://'+SERVER+':8080/api/v1/yuva/hraPdfReport/status'


  // Load section question
  export const section9QThunk = createAsyncThunk(
   'section9/section9QThunk',
   async ({jwt}, {fulfillWithValue, rejectWithValue}) => {
       try {
            const authToken = 'Bearer '+jwt
            console.log(authToken)
            return await axios.get(SECTION_QUESTION, {
              headers: {
              'Content-Type': 'application/json',
              'Authorization':authToken
              }
            })
            .then(resp => resp.data)
       }catch(error){
           //const errorOject =  JSON.stringify(error.response.data)
           console.log(error)
           return rejectWithValue(error.response.data)
       }
   } 
 )

/**
 * Check the status of the report
 */
  export const reportStatusThunk = createAsyncThunk(
    'section9/status',
    async ({jwt}, {fulfillWithValue, rejectWithValue}) => {
        try {
             const authToken = 'Bearer '+jwt
             console.log(authToken)
             return await axios.get(CHECK_REPORT, {
               headers: {
               'Content-Type': 'application/json',
               'Authorization':authToken
               }
             })
             .then(async (resp) => {
               console.log(resp)

               return resp.data
